const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define UK geometry and date ranges
  const uk = ee.Geometry.Rectangle([-8, 50, 2, 59]);

  // Target period: Feb 11-25, 2019
  const startDate2019 = '2019-02-11';
  const endDate2019 = '2019-02-25';

  // Historical period: Feb 11-25, 2000-2012 (average)
  const historicalYears = [2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012];

  // 2. Collect 2019 data
  const lst2019 = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterBounds(uk)
    .filterDate(startDate2019, '2019-02-26')
    .select('LST_Day_1km');

  const count2019 = lst2019.size().getInfo();
  console.log(`2019 Feb 11-25: ${count2019} images`);

  if (count2019 === 0) {
    console.log('C1: No images found for 2019');
    console.log('C1');
    return;
  }

  // 3. Collect historical data (2000-2012, same period)
  let historicalCollection = ee.ImageCollection([]);
  for (let year of historicalYears) {
    const startDate = `${year}-02-11`;
    const endDate = `${year}-02-26`;
    const yearCollection = ee.ImageCollection('MODIS/006/MOD11A1')
      .filterBounds(uk)
      .filterDate(startDate, endDate)
      .select('LST_Day_1km');
    historicalCollection = historicalCollection.merge(yearCollection);
  }

  const countHistorical = historicalCollection.size().getInfo();
  console.log(`2000-2012 Feb 11-25: ${countHistorical} images`);

  if (countHistorical === 0) {
    console.log('C1: No historical images found');
    console.log('C1');
    return;
  }

  // 4. Calculate mean LST for 2019 (convert from K*0.02 to K)
  const mean2019Img = lst2019.mean().multiply(0.02);
  const stats2019 = mean2019Img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: uk,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const val2019 = stats2019['LST_Day_1km'];
  const validPixels2019 = lst2019.first().reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: uk,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo()['LST_Day_1km'];

  console.log(`2019 LST: ${val2019 !== null ? (val2019 - 273.15).toFixed(2) : 'null'}°C, Pixels: ${validPixels2019}`);

  if (validPixels2019 === 0 || val2019 === null) {
    console.log('C2: No valid pixels in 2019');
    console.log('C2');
    return;
  }

  // 5. Calculate mean LST for historical period (2000-2012)
  const meanHistoricalImg = historicalCollection.mean().multiply(0.02);
  const statsHistorical = meanHistoricalImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: uk,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const valHistorical = statsHistorical['LST_Day_1km'];
  const validPixelsHistorical = historicalCollection.first().reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: uk,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo()['LST_Day_1km'];

  console.log(`2000-2012 LST: ${valHistorical !== null ? (valHistorical - 273.15).toFixed(2) : 'null'}°C, Pixels: ${validPixelsHistorical}`);

  if (validPixelsHistorical === 0 || valHistorical === null) {
    console.log('C2: No valid pixels in historical data');
    console.log('C2');
    return;
  }

  // 6. Validate LST ranges (should be 250-330 K)
  if (val2019 < 250 || val2019 > 330 || valHistorical < 250 || valHistorical > 330) {
    console.log(`C3: Invalid LST values (2019: ${val2019}K, Hist: ${valHistorical}K)`);
    console.log('C3');
    return;
  }

  // 7. Compare
  const diff = val2019 - valHistorical;
  console.log(`Difference: ${diff.toFixed(2)}K (${(diff * 1.8).toFixed(2)}°C increase)`);

  if (diff > 0) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
